UPDATE TB_EVENT
SET STATUS = 'DELETED', UPDATED_BY = #{username}
WHERE EVENT_ID = #{eventId}

UPDATE TB_EVENT
SET STATUS = #{status}, UPDATED_BY = #{updatedBy}
WHERE EVENT_ID = #{eventId}

mapper.select:
SELECT DISTINCT e.*, u.NAME as OWNER_NAME, c.CALENDAR_NAME as CALENDAR_NAME, c.COLOR as CALENDAR_COLOR, g.GROUP_NAME as GROUP_NAME, g.GROUP_COLOR as GROUP_COLOR, CASE WHEN e.OWNER_USERNAME = #{username} THEN FALSE ELSE TRUE END as IS_SHARED, COALESCE(es.SHARED_BY, cs.SHARED_BY) as SHARED_BY_USERNAME, COALESCE(esu.NAME, csu.NAME) as SHARED_BY_NAME, COALESCE(es.SHARE_TYPE, cs.SHARE_TYPE) as SHARE_TYPE, CASE WHEN e.OWNER_USERNAME = #{username} THEN 'OWNER' WHEN es.SHARE_TYPE IS NOT NULL THEN es.SHARE_TYPE WHEN cs.SHARE_TYPE IS NOT NULL THEN cs.SHARE_TYPE WHEN ug.USER_GROUP_ID IS NOT NULL THEN 'EDIT' ELSE NULL END as ACCESS_TYPE, CASE WHEN e.OWNER_USERNAME != #{username} AND e.GROUP_ID IS NOT NULL AND ug.USER_GROUP_ID IS NOT NULL THEN TRUE ELSE FALSE END as IS_GROUP_SHARED FROM TB_EVENT e INNER JOIN TB_CALENDAR c ON e.CALENDAR_ID = c.CALENDAR_ID AND c.USE_YN = 'Y' LEFT JOIN TB_USER u ON e.OWNER_USERNAME = u.USERNAME LEFT JOIN TB_GROUP g ON e.GROUP_ID = g.GROUP_ID LEFT JOIN TB_EVENT_SHARE es ON e.EVENT_ID = es.EVENT_ID AND es.USERNAME = #{username} AND es.DELETED_AT IS NULL LEFT JOIN TB_USER esu ON es.SHARED_BY = esu.USERNAME LEFT JOIN TB_CALENDAR_SHARE cs ON c.CALENDAR_ID = cs.CALENDAR_ID AND cs.USERNAME = #{username} AND cs.DELETED_AT IS NULL LEFT JOIN TB_USER csu ON cs.SHARED_BY = csu.USERNAME LEFT JOIN TB_USER_GROUP ug ON e.GROUP_ID = ug.GROUP_ID AND ug.USERNAME = #{username} AND ug.DELETED_AT IS NULL WHERE e.STATUS = 'ACTIVE' AND ( /* 일반 이벤트: 날짜 범위 내 */ (e.IS_RECURRING = FALSE AND e.START_DATE <= #{endDate} AND COALESCE(e.END_DATE, e.START_DATE) >= #{startDate}) OR /* 반복 이벤트: 시작일이 종료일 이전이고, 반복 종료일이 없거나 시작일 이후 */ (e.IS_RECURRING = TRUE AND e.START_DATE <= #{endDate} AND (e.RECURRENCE_END_DATE IS NULL OR e.RECURRENCE_END_DATE >= #{startDate})) ) AND ( e.OWNER_USERNAME = #{username}
OR es.EVENT_SHARE_ID IS NOT NULL OR cs.CALENDAR_SHARE_ID IS NOT NULL /* 그룹 공유: 그룹 멤버인 경우 */ OR (e.GROUP_ID IS NOT NULL AND ug.USER_GROUP_ID IS NOT NULL)
)
AND e.CALENDAR_ID = #{calendarId}
AND e.GROUP_ID = #{groupId}
ORDER BY e.START_DATE, e.START_TIME, e.TITLE

SELECT COUNT(*) > 0
FROM TB_EVENT e
INNER JOIN TB_CALENDAR c ON e.CALENDAR_ID = c.CALENDAR_ID
LEFT JOIN TB_EVENT_SHARE es ON e.EVENT_ID = es.EVENT_ID
    AND es.USERNAME = #{username}
    AND es.DELETED_AT IS NULL
LEFT JOIN TB_CALENDAR_SHARE cs ON c.CALENDAR_ID = cs.CALENDAR_ID
    AND cs.USERNAME = #{username}
    AND cs.DELETED_AT IS NULL
LEFT JOIN TB_USER_GROUP ug ON e.GROUP_ID = ug.GROUP_ID
    AND ug.USERNAME = #{username}
    AND ug.DELETED_AT IS NULL
WHERE e.EVENT_ID = #{eventId}
  AND e.STATUS != 'DELETED'
  AND (
      e.OWNER_USERNAME = #{username}
      OR es.EVENT_SHARE_ID IS NOT NULL
      OR cs.CALENDAR_SHARE_ID IS NOT NULL
      OR (e.GROUP_ID IS NOT NULL AND ug.USER_GROUP_ID IS NOT NULL)
  )
